// next_action=TEST: mail šel jen tobě (TEST_MODE) – po přepnutí na ostro dostane firma 1. e-mail znovu, tentokrát skutečně

// ---- společné pomocné funkce (stejné ve všech workflowech) ----
const env = (k, d = '') => { const v = $env[k]; return (v === undefined || v === null || v === '') ? d : String(v); };
const clean = (items) => (items || []).map(i => (i && i.json !== undefined) ? i.json : i)
  .filter(j => j && typeof j === 'object' && Object.values(j).some(v => v !== '' && v !== null && v !== undefined));
const blockedCountries = () => { const s = new Set(env('BLOCKED_COUNTRIES', 'CR').split(',').map(x => x.trim().toUpperCase()).filter(Boolean)); s.add('CR'); return s; };
const domainOf = (e) => { const m = String(e || '').toLowerCase().match(/@([a-z0-9.-]+)/); return m ? m[1] : ''; };
const domainOfUrl = (u) => { try { if (!u) return ''; const h = new URL(/^https?:\/\//i.test(u) ? u : 'http://' + u).hostname.toLowerCase(); return h.replace(/^www\./, ''); } catch (e) { return ''; } };
const FREE_MAIL = new Set(['gmail.com','googlemail.com','seznam.cz','email.cz','centrum.cz','volny.cz','atlas.cz','post.cz','tiscali.cz','yahoo.com','yahoo.co.uk','yahoo.ca','yahoo.com.au','hotmail.com','hotmail.co.uk','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','mail.com','gmx.com','gmx.de','web.de','bigpond.com','shaw.ca','telus.net','rogers.com','comcast.net','att.net','verizon.net','btinternet.com','sky.com','virginmedia.com']);
const parseISO = (s) => { if (!s) return null; const d = DateTime.fromISO(String(s)); return d.isValid ? d : null; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

// ---- sestavení MIME zprávy pro Gmail API (raw, base64url) ----
function buildMime(o) {
  const B = (typeof Buffer !== 'undefined') ? Buffer : require('buffer').Buffer;
  const encW = (s) => /[^\x00-\x7F]/.test(s) ? '=?UTF-8?B?' + B.from(s, 'utf8').toString('base64') + '?=' : s;
  const b64 = (s) => B.from(s, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n');
  const boundary = 'np_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  const head = [`From: ${encW(o.fromName)} <${o.fromEmail}>`, `To: ${o.to}`, `Subject: ${encW(o.subject)}`, 'MIME-Version: 1.0'];
  if (o.inReplyTo) head.push(`In-Reply-To: ${o.inReplyTo}`);
  if (o.references) head.push(`References: ${o.references}`);
  if (o.unsubscribe) head.push(`List-Unsubscribe: <${o.unsubscribe}>`);
  head.push('X-Outreach-Bot: 1');
  head.push(`Content-Type: multipart/alternative; boundary="${boundary}"`);
  const parts = [`--${boundary}`, 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', b64(o.text || ''),
                 `--${boundary}`, 'Content-Type: text/html; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', b64(o.html || ''), `--${boundary}--`, ''];
  const msg = head.join('\r\n') + '\r\n\r\n' + parts.join('\r\n');
  return B.from(msg, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const textToHtml = (t) => '<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.5;color:#1f1f1f;">' +
  esc(t).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" style="color:#1f1f1f;">$1</a>').replace(/\n/g, '<br>') + '</div>';

const l = $('Smyčka odeslání').item.json;
const meta = $input.item.json || {};
const hdrs = ((meta.payload || {}).headers || []);
const h = (n) => { const x = hdrs.find(y => String(y.name).toLowerCase() === n.toLowerCase()); return x ? String(x.value) : ''; };
const origMsgId = h('Message-ID');
const origSubject = h('Subject');
const subject = origSubject ? (/^re:/i.test(origSubject) ? origSubject : 'Re: ' + origSubject) : 'Re: ' + l.subject;
const references = [h('References'), origMsgId].filter(Boolean).join(' ');
const raw = buildMime({ fromName: l.from_name, fromEmail: l.from_email, to: l.to, subject, text: l.text, html: l.html,
  inReplyTo: origMsgId, references, unsubscribe: l.unsubscribe_url });
return { json: { raw, threadId: meta.threadId || l.thread_id || '', subject } };

const r = $input.item.json || {};
const l = $('Smyčka odeslání').item.json;
const row = { id: l.id, status: 'sent_' + l.step, thread_id: r.threadId || l.thread_id || '', last_message_id: r.id || '', next_action: (String($env.TEST_MODE ?? 'true').toLowerCase() === 'true') ? 'TEST' : '' };
row['sent_' + l.step + '_at'] = DateTime.now().toISO();
return { json: row };
